package br.com.ajudamutua.service;
import br.com.ajudamutua.model.AuditEvent; import br.com.ajudamutua.repository.AuditEventRepository; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*;
@Service public class AuditService {private static final String GENESIS="0".repeat(64);private final AuditEventRepository repo;private final JdbcTemplate jdbc;public AuditService(AuditEventRepository repo,JdbcTemplate jdbc){this.repo=repo;this.jdbc=jdbc;}
 @Transactional public AuditEvent append(UUID actor,String action,String entityType,UUID entityId,String metadata){jdbc.queryForObject("select id from audit_chain_lock where id=1 for update",Integer.class);String prev=repo.findTopByOrderByCreatedAtDesc().map(AuditEvent::getEventHash).orElse(GENESIS);UUID id=UUID.randomUUID();Instant now=Instant.now();String payload=id+"|"+actor+"|"+action+"|"+entityType+"|"+entityId+"|"+metadata+"|"+now+"|"+prev;return repo.save(new AuditEvent(id,actor,action,entityType,entityId,metadata,now,prev,sha(payload)));}
 public List<AuditEvent> all(){return repo.findAll(org.springframework.data.domain.Sort.by("createdAt").descending());}private String sha(String x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
